INSERT INTO `categories` (`id`, `name`, `abbreviation`, `abbreviation_description`, `slug`, `description`, `category_image`, `status`, `admin_status`, `display_on_menu`, `note`, `group_id`, `created_at`, `updated_at`) VALUES
(7, 'Rules & Regulations', 'R & R', NULL, 'rules-regulations', 'This category comprises rules and other regulatory instruments issued by FMDQ Exchange, the Securities and Exchange Commission, and other relevant regulatory authorities, to provide the governance framework for markets within their respective regulatory remits and regulate the conduct of market participants. They include, among others, rules governing the trading of financial market products, the registration, listing, and quotation of securities, and standards of conduct applicable to participants in the Nigerian financial market.', 'rules-regulations-1768890379.jpg', '1', '1', '1', NULL, '4', '2023-01-18 09:17:27', '2026-01-20 06:26:55'),
(31, 'Product and Market Documentation', 'PMD', NULL, 'product-market-documentation', 'Products & Market Documentation refers to the set of documents that provide information, standards, and guidance on FMDQ Exchange products and market operations, including the Product Information, Market Framework, Operational Modalities, Pricing Methodologies, and Risk Management Documentation.', 'product-market-documentation-1768558550.jpg', '1', '1', '1', NULL, '5', '2026-01-16 10:15:50', '2026-01-20 06:24:30'),
(32, 'Others', 'Others', NULL, 'others', 'This category accommodates relevant market materials that do not fall strictly under Product Market Documentation or Rules and Regulations. It contains supplementary publications, guidance notes, and informational releases that provide additional insight into market operations', 'others-1768890587.jpg', '1', '1', '1', NULL, '5', '2026-01-20 06:29:47', '2026-01-20 06:30:11');

