INSERT INTO `subcategories` (`id`, `category_id`, `name`, `abbreviation`, `abbreviation_description`, `slug`, `summary`, `status`, `admin_status`, `note`, `group_id`, `created_at`, `updated_at`) VALUES
(61, '7', 'Full Rule Book and other Regulations', 'FRBR', NULL, 'full-rule-book-and-other-regulations', 'This subcategory hosts the rules and regulation issued by FMDQ Exchange, the Securities and Exchange Commission and other relevant regulatory bodies that govern participation and conduct within the Nigerian financial markets. It provides for all relevant regulatory frameworks that underpin market operations, regulate market participant conduct, support market integrity and ensure effective supervision across the Nigerian financial market', 1, '1', NULL, '5', '2026-01-20 08:26:53', '2026-01-20 10:26:01'),
(62, '32', 'Market Bulletin and Specific Amendments', 'MBSA', NULL, 'market-bulletin-and-specific-amendments', 'This subcategory sets out Market Bulletins issued by FMDQ Exchange to provide information to market participants on a variety of regulatory issues ranging from the introduction of new regulation, to changes to existing regulation, and guidance in relation to compliance with regulation as may be prescribed by the Exchange from time to time.', 1, '1', NULL, '5', '2026-01-20 08:51:21', '2026-01-20 10:25:51'),
(63, '32', 'Full Rule Book and other Regulations', 'FRBR', NULL, 'full-rule-book-and-other-regulations', 'This subcategory hosts the rules and regulation issued by FMDQ Exchange, the Securities and Exchange Commission and other relevant regulatory bodies that govern participation and conduct within the Nigerian financial markets. It provides for all relevant regulatory frameworks that underpin market operations, regulate market participant conduct, support market integrity and ensure effective supervision across the Nigerian financial market', 1, '1', NULL, '5', '2026-01-20 08:56:02', '2026-01-20 10:25:44'),
(64, '31', 'Market Notices', 'MN', NULL, 'market-notices', 'These are periodic communications issued by FMDQ Exchange to keep market participants informed about products and market developments. They cover matters such as new product launches, updates to operational procedures, risk management arrangements, and other relevant market activities.', 1, '1', NULL, '5', '2026-01-20 08:58:05', '2026-01-20 10:24:18'),
(65, '31', 'Framework and Methodology', 'FM', NULL, 'framework-and-methodology', 'These categories include the pricing methodologies, frameworks, operational modalities adopted by FMDQ Exchange to guide market operations. It promotes transparency by outlining how standards are developed, how assessments are carried out, and how key metrics and market measures are determined. It provides clarity on the principles, processes, and criteria underpinning market standards, assessments, and key market measures', 1, '1', NULL, '5', '2026-01-20 08:59:52', '2026-01-20 10:22:57'),
(66, '31', 'Product Information Memorandum', 'PI', NULL, 'product-information-memorandum', 'These documents provide detailed information on the features, specifications, and operational requirements of FMDQ Exchange’s products. They serve as reference materials for users seeking to understand product offerings, usage requirements, and performance characteristics', 1, '1', NULL, '5', '2026-01-20 09:49:52', '2026-01-20 10:22:47'),
(67, '31', 'Risk Management Documentation', 'RMD', NULL, 'risk-management-documentation', 'This category covers the policies, controls, and procedures established by FMDQ Exchange to identify, monitor, and mitigate risks across its market operations. These documents support sound risk governance and help ensure the stability and integrity of the Exchange’s markets.', 1, '1', NULL, '5', '2026-01-20 09:51:55', '2026-01-20 10:22:36'),
(68, '32', 'CBN Publication', NULL, NULL, 'cbn-publication', 'This subcategory covers all informational and administrative documents issued by the Central Bank of Nigeria (“CBN”). These include circulars, letters, directives, press releases, and policy statements that communicate updates, policy decisions, and operational information to the public and participants in the Nigerian financial market.', 1, '1', NULL, '5', '2026-01-20 10:14:06', '2026-01-20 10:22:09'),
(69, '32', 'CBN Guideline', NULL, NULL, 'cbn-guideline', 'These are comprehensive frameworks that set out regulatory instructions issued by the CBN. They provide authoritative guidance on the operations of financial institutions and market participants, establishing requirements on market conduct, product standards, reporting obligations, and risk management for regulated entities.', 1, '1', NULL, '5', '2026-01-20 10:15:13', '2026-01-20 10:21:56'),
(70, '32', 'Market Notices', NULL, NULL, 'market-notices', 'These are periodic communications issued by FMDQ Exchange to keep market participants informed about products and market developments. They cover matters such as new product launches, updates to operational procedures, risk management arrangements, and other relevant market activities.', 1, '1', NULL, '5', '2026-01-20 10:16:40', '2026-01-20 10:21:49');

